0 _thv.SunTextureId="rbxasset://sky/moon.jpg"_thv.CelestialBodiesShown=true _thv.Parent=Lighting-- Atmosphere (Thick, moody cinematic night fog for RTX vibe)local _pnk=Instance.new("Atmosphere")_pnk.Name="Atmosphere"_pnk.Density=0.25 _pnk.Offset=0.25 _pnk.Color=Color3.fromRGB(30,30,40)_pnk.Decay=Color3.fromRGB(15,15,25)_pnk.Glare=0.1 _pnk.Haze=0.2 _pnk.Parent=Lighting-- Bloom (Sharp and crisp for stars and lights)local _ddp=Instance.new("BloomEffect")_ddp.Enabled=true _ddp.Intensity=1.0 _ddp.Size=16 _ddp.Threshold=1.5 _ddp.Parent=Lighting-- Depth of Field (DSLR RTX focus)local _gft=Instance.new("DepthOfFieldEffect")_gft.Enabled=true _gft.FarIntensity=0.1 _gft.NearIntensity=0.75 _gft.FocusDistance=0.05 _gft.InFocusRadius=30 _gft.Parent=Lighting-- Color Correction (Desaturated, cinematic night)local _kqc=Instance.new("ColorCorrectionEffect")_kqc.Enabled=true _kqc.Brightness=0.02 _kqc.Contrast=0.1 _kqc.Saturation=-0.1 _kqc.TintColor=Color3.fromRGB(200,220,255)-- Dark blue typish tint for the whole scene_kqc.Parent=Lighting-- SunRays (Very subtle for moon rays)local _zfk=Instance.new("SunRaysEffect")_zfk.Enabled=true _zfk.Intensity=0.05 _zfk.Spread=0.5 _zfk.Parent=Lighting-- RTX Terrain & Volumetric Cloudsif _msh:FindFirstChildOfClass("Terrain")then _msh.Terrain.Decoration=true for _djy,_xrs in ipairs(_msh.Terrain:GetChildren())do if _xrs:IsA("Clouds")then _xrs:Destroy()end end local _tey=Instance.new("Clouds")_tey.Name="RTX_Clouds"_tey.Cover=1.0-- Extremely high_tey.Density=1.0-- Thicker_tey.Color=Color3.fromRGB(80,90,110)_tey.Parent=_msh.Terrain end end,["pink.lua"]=function()local Players=game:GetService("Players")local Lighting=game:GetService("Lighting")local _msh=game:GetService("Workspace")-- Wipe any old snapshot firstgetgenv().ORIGINAL_COLORS=setmetatable({},{__mode="k"})getgenv().ORIGINAL_LIGHTING={}getgenv().ORIGINAL_WATER=nil getgenv().ORIGINAL_SKY=nil getgenv().ORIGINAL_ATMO=nil local function isCharacterPart(_yo)local _bee=_yo:FindFirstAncestorOfClass("Model")return _bee and _bee:FindFirstChildOfClass("Humanoid")~=nil end -- -------------------------------------------------- Snapshot every BasePart color in the workspace-- ------------------------------------------------local _nye=0 for _djy,_wdj in ipairs(_msh:GetDescendants())do if _wdj:IsA("BasePart")and not isCharacterPart(_wdj)then pcall(function()getgenv().ORIGINAL_COLORS[_wdj]=_wdj.Color _nye+=1 end)end end -- Also snapshot colors of parts that load in later_msh.DescendantAdded:Connect(function(_wdj)if _wdj:IsA(_dfzuq({116,85,32,90,102,85,33,75},{54,52,83,63}))and not isCharacterPart(_wdj)then pcall(function()if not getgenv().ORIGINAL_COLORS[_wdj]then getgenv().ORIGINAL_COLORS[_wdj]=_wdj.Color end end)end end)-- -------------------------------------------------- Snapshot all Lighting properties-- ------------------------------------------------local L=getgenv().ORIGINAL_LIGHTING L.Technology=Lighting.Technology L.Ambient=Lighting.Ambient L.OutdoorAmbient=Lighting.OutdoorAmbient L.Brightness=Lighting.Brightness L.ColorShift_Bottom=Lighting.ColorShift_Bottom L.ColorShift_Top=Lighting.ColorShift_Top L.FogColor=Lighting.FogColor L.FogEnd=Lighting.FogEnd L.FogStart=Lighting.FogStart L.GlobalShadows=Lighting.GlobalShadows L.ShadowSoftness=Lighting.ShadowSoftness L.EnvironmentDiffuseScale=Lighting.EnvironmentDiffuseScale L.EnvironmentSpecularScale=Lighting.EnvironmentSpecularScale L.ExposureCompensation=Lighting.ExposureCompensation L.ClockTime=Lighting.ClockTime L.GeographicLatitude=Lighting.GeographicLatitude-- -------------------------------------------------- Snapshot existing Sky if present-- ------------------------------------------------local _prw=Lighting:FindFirstChildOfClass("Sky")if _prw then getgenv().ORIGINAL_SKY={SkyboxBk=_prw.SkyboxBk,SkyboxDn=_prw.SkyboxDn,SkyboxFt=_prw.SkyboxFt,SkyboxLf=_prw.SkyboxLf,SkyboxRt=_prw.SkyboxRt,SkyboxUp=_prw.SkyboxUp,CelestialBodiesShown=_prw.CelestialBodiesShown,StarCount=_prw.StarCount,}end -- -------------------------------------------------- Snapshot existing Atmosphere if present-- ------------------------------------------------local _jxa=Lighting:FindFirstChildOfClass("Atmosphere")if _jxa then getgenv().ORIGINAL_ATMO={Density=_jxa.Density,Offset=_jxa.Offset,Color=_jxa.Color,Decay=_jxa.Decay,Glare=_jxa.Glare,Haze=_jxa.Haze,}end -- -------------------------------------------------- Snapshot Terrain water-- ------------------------------------------------local Terrain=_msh:FindFirstChildOfClass("Terrain")if Terrain then getgenv().ORIGINAL_WATER={WaterColor=Terrain.WaterColor,WaterReflectance=Terrain.WaterReflectance,WaterTransparency=Terrain.WaterTransparency,WaterWaveSize=Terrain.WaterWaveSize,WaterWaveSpeed=Terrain.WaterWaveSpeed,}end print(string.format("[Snapshot] Ready. Saved %d part colors, lighting, sky, atmosphere & water. Safe to run shaders.",_nye))-- LocalScript in StarterPlayerScriptslocal _msh=game:GetService("Workspace")local function applyLightPink(_yo)if _yo:IsA("BasePart")or _yo:IsA("Terrain")then if isCharacterPart(_yo)then return end if _yo.Name=="PandaTile"then return end if _yo:IsA("Terrain")then _yo.WaterColor=Color3.fromRGB(255,200,220)else local _xrs=_yo.Color local _bph=0.299*_xrs.R+0.587*_xrs.G+0.114*_xrs.B _yo.Color=Color3.new(0.85+_bph*0.15,-- R: very high0.65+_bph*0.15,-- G: medium-high0.70+_bph*0.15-- B: medium-high)end end end for _djy,_wdj in ipairs(_msh:GetDescendants())do applyLightPink(_wdj)end _msh.DescendantAdded:Connect(applyLightPink)-- PINK SHADER WITH RTX LIGHTING V2 (from Empty Tools)local Lighting=game:GetService("Lighting")-- Clear old lightingLighting:ClearAllChildren()-- Lighting PropertiesLighting.Ambient=Color3.fromRGB(100,65,115)Lighting.OutdoorAmbient=Color3.fromRGB(160,110,180)Lighting.Brightness=2.4-- slightly dimmed from 3Lighting.ColorShift_Bottom=Color3.fromRGB(255,160,210)Lighting.ColorShift_Top=Color3.fromRGB(200,130,240)Lighting.EnvironmentDiffuseScale=1 Lighting.EnvironmentSpecularScale=1 Lighting.GlobalShadows=true Lighting.ShadowSoftness=0.25 Lighting.ClockTime=14 Lighting.GeographicLatitude=25 Lighting.ExposureCompensation=-0.2-- subtle exposure pull-down-- Skyboxlocal _ivf=Instance.new("Sky")_ivf.SkyboxBk="http://www.roblox.com/asset/?id=271042516"_ivf.SkyboxDn="http://www.roblox.com/asset/?id=271077243"_ivf.SkyboxFt="http://www.roblox.com/asset/?id=271042556"_ivf.SkyboxLf="http://www.roblox.com/asset/?id=271042310"_ivf.SkyboxRt="http://www.roblox.com/asset/?id=271042467"_ivf.SkyboxUp="http://www.roblox.com/asset/?id=271077958"_ivf.CelestialBodiesShown=true _ivf.StarCount=5000 _ivf.Parent=Lighting-- Atmosphere (RTX-style haze & scatter)local _lbe=Instance.new("Atmosphere")_lbe.Density=0.45 _lbe.Offset=0.3 _lbe.Color=Color3.fromRGB(255,170,215)_lbe.Decay=Color3.fromRGB(160,85,145)_lbe.Glare=0.55 _lbe.Haze=0.2 _lbe.Parent=Lighting-- Bloom (punchy glow)local _ddp=Instance.new("BloomEffect")_ddp.Enabled=true _ddp.Intensity=0.6 _ddp.Size=28 _ddp.Threshold=0.85 _ddp.Parent=Lighting-- Color Correctionlocal _kqc=Instance.new("ColorCorrectionEffect")_kqc.Contrast=0.05 _kqc.TintColor=Color3.fromRGB(245,220,255)_kqc.Saturation=0.35 _kqc.Brightness=0.02 _kqc.Enabled=true _kqc.Parent=Lighting-- Sun Rays (volumetric light shafts)local _zfk=Instance.new("SunRaysEffect")_zfk.Enabled=true _zfk.Intensity=0.35 _zfk.Spread=0.75 _zfk.Parent=Lighting-- Depth of Field (cinematic blur)local _gft=Instance.new("DepthOfFieldEffect")_gft.Enabled=false _gft.FarIntensity=0.55 _gft.NearIntensity=0.15 _gft.FocusDistance=45 _gft.InFocusRadius=30 _gft.Parent=Lighting-- Motion Blur (movement feel)local _bkl=Instance.new("BlurEffect")_bkl.Enabled=false _bkl.Size=6 _bkl.Parent=Lighting-- Film Grain (cinematic texture)-- Simulated via a subtle ColorCorrectionEffect layered on toplocal _cdr=Instance.new("ColorCorrectionEffect")_cdr.Contrast=0.08 _cdr.Saturation=0.1 _cdr.TintColor=Color3.fromRGB(255,235,255)_cdr.Enabled=true _cdr.Parent=Lighting-- Optional Cloudsif not workspace.Terrain:FindFirstChildOfClass("Clouds")then local _tey=Instance.new("Clouds")_tey.Cover=0.72 _tey.Density=0.62 _tey.Color=Color3.fromRGB(255,140,200)_tey.Parent=workspace.Terrain end end,["red_cosmos.lua"]=function()local Players=game:GetService("Players")local Lighting=game:GetService("Lighting")local _msh=game:GetService("Workspace")-- Wipe any old snapshot firstgetgenv().ORIGINAL_COLORS=setmetatable({},{__mode="k"})getgenv().ORIGINAL_LIGHTING={}getgenv().ORIGINAL_WATER=nil getgenv().ORIGINAL_SKY=nil getgenv().ORIGINAL_ATMO=nil local function isCharacterPart(_yo)local _bee=_yo:FindFirstAncestorOfClass("Model")return _bee and _bee:FindFirstChildOfClass("Humanoid")~=nil end -- -------------------------------------------------- Snapshot every BasePart color in the workspace-- ------------------------------------------------local _nye=0 for _djy,_wdj in ipairs(_msh:GetDescendants())do if _wdj:IsA("BasePart")and not isCharacterPart(_wdj)then pcall(function()getgenv().ORIGINAL_COLORS[_wdj]=_wdj.Color _nye+=1 end)end end _msh.DescendantAdded:Connect(function(_wdj)if _wdj:IsA(_dfzuq({14,12,39,20,111,29,62,25},{76,109,84,113,63,124}))and not isCharacterPart(_wdj)then pcall(function()if not getgenv().ORIGINAL_COLORS[_wdj]then getgenv().ORIGINAL_COLORS[_wdj]=_wdj.Color end end)end end)-- -------------------------------------------------- Snapshot all Lighting properties-- ------------------------------------------------local L=getgenv().ORIGINAL_LIGHTING L.Technology=Lighting.Technology L.Ambient=Lighting.Ambient L.OutdoorAmbient=Lighting.OutdoorAmbient L.Brightness=Lighting.Brightness L.ColorShift_Bottom=Lighting.ColorShift_Bottom L.ColorShift_Top=Lighting.ColorShift_Top L.FogColor=Lighting.FogColor L.FogEnd=Lighting.FogEnd L.FogStart=Lighting.FogStart L.GlobalShadows=Lighting.GlobalShadows L.ShadowSoftness=Lighting.ShadowSoftness L.EnvironmentDiffuseScale=Lighting.EnvironmentDiffuseScale L.EnvironmentSpecularScale=Lighting.EnvironmentSpecularScale L.ExposureCompensation=Lighting.ExposureCompensation L.ClockTime=Lighting.ClockTime L.GeographicLatitude=Lighting.GeographicLatitude-- -------------------------------------------------- Snapshot existing Sky & Atmo-- ------------------------------------------------local _prw=Lighting:FindFirstChildOfClass("Sky")if _prw then getgenv().ORIGINAL_SKY={SkyboxBk=_prw.SkyboxBk,SkyboxDn=_prw.SkyboxDn,SkyboxFt=_prw.SkyboxFt,SkyboxLf=_prw.SkyboxLf,SkyboxRt=_prw.SkyboxRt,SkyboxUp=_prw.SkyboxUp,CelestialBodiesShown=_prw.CelestialBodiesShown,StarCount=_prw.StarCount,}end local _jxa=Lighting:FindFirstChildOfClass("Atmosphere")if _jxa then getgenv().ORIGINAL_ATMO={Density=_jxa.Density,Offset=_jxa.Offset,Color=_jxa.Color,Decay=_jxa.Decay,Glare=_jxa.Glare,Haze=_jxa.Haze,}end -- -------------------------------------------------- Snapshot Terrain water-- ------------------------------------------------local Terrain=_msh:FindFirstChildOfClass("Terrain")if Terrain then getgenv().ORIGINAL_WATER={WaterColor=Terrain.WaterColor,WaterReflectance=Terrain.WaterReflectance,WaterTransparency=Terrain.WaterTransparency,WaterWaveSize=Terrain.WaterWaveSize,WaterWaveSpeed=Terrain.WaterWaveSpeed,}end print(string.format("[Snapshot] Ready. Saved %d part colors, lighting, sky, atmosphere & water. Safe to run shaders.",_nye))-- -------------------------------------------------- Apply Red Cosmos Colors-- ------------------------------------------------local function toRedTint(_xrs)local _bph=0.299*_xrs.R+0.587*_xrs.G+0.114*_xrs.B-- A much softer, desaturated red/gray tintreturn Color3.new(_bph*0.9,_bph*0.65,_bph*0.65)end local _qir={}local function applyTint(_yo)if not _yo:IsA('BasePart')and not _yo:IsA('Terrain')then return end if _yo.Name=="PandaTile"then return end if _qir[_yo]then return end if isCharacterPart(_yo)then return end _qir[_yo]=true if _yo:IsA("Terrain")then _yo.WaterColor=Color3.fromRGB(180,20,20)else _yo.Color=toRedTint(_yo.Color)end end for _djy,_wdj in ipairs(workspace:GetDescendants())do pcall(applyTint,_wdj)end workspace.DescendantAdded:Connect(function(_xwg)task.defer(function()pcall(applyTint,_xwg)end)end)local function protectAvatar(char)if not char then return end for _djy,_yo in ipairs(char:GetDescendants())do pcall(function()if _yo:IsA(_dfzuq({45,22,61,21,51,14,5,58},{111,119,78,112,99}))and _qir[_yo]then _qir[_yo]=nil end end)end char.DescendantAdded:Connect(function(_xwg)task.defer(function()pcall(function()if _xwg:IsA(_dfzuq({57,6,56,54,119,34,9,19},{123,103,75,83,39,67}))then _qir[_xwg]=nil end end)end)end)end for _djy,_usj in ipairs(Players:GetPlayers())do protectAvatar(_usj.Character)_usj.CharacterAdded:Connect(protectAvatar)end Players.PlayerAdded:Connect(function(_usj)protectAvatar(_usj.Character)_usj.CharacterAdded:Connect(protectAvatar)end)-- -------------------------------------------------- Apply Red Cosmos Lighting & Skybox-- ------------------------------------------------Lighting:ClearAllChildren()local _zba=Instance.new('Sky')_zba.SkyboxBk='http://www.roblox.com/asset/?id=15542476630'_zba.SkyboxDn='http://www.roblox.com/asset/?id=15542477272'_zba.SkyboxFt='http://www.roblox.com/asset/?id=15542481240'_zba.SkyboxLf='http://www.roblox.com/asset/?id=15542482020'_zba.SkyboxRt='http://www.roblox.com/asset/?id=15542483287'_zba.SkyboxUp='http://www.roblox.com/asset/?id=15542484852'_zba.StarCount=3000 _zba.SunAngularSize=21 _zba.SunTextureId="rbxassetid://1084351190"_zba.Parent=Lighting local _rpb=Instance.new('Atmosphere')_rpb.Density=0.25 _rpb.Offset=0.15 _rpb.Color=Color3.fromRGB(180,80,80)_rpb.Decay=Color3.fromRGB(80,30,40)_rpb.Glare=0.05 _rpb.Haze=0.05 _rpb.Parent=Lighting Lighting.Ambient=Color3.fromRGB(110,80,80)Lighting.OutdoorAmbient=Color3.fromRGB(130,90,90)Lighting.ColorShift_Top=Color3.fromRGB(255,190,190)Lighting.ColorShift_Bottom=Color3.fromRGB(80,50,50)Lighting.FogColor=Color3.fromRGB(30,10,15)Lighting.FogEnd=999999 Lighting.Brightness=1.8 Lighting.ExposureCompensation=0 Lighting.GlobalShadows=true Lighting.ClockTime=12-- 90-degree angle (directly overhead)Lighting.GeographicLa